INSERT INTO settlement (
    settlement_id, seller_id, period_start, period_end,
    gross_amount, commission_amount, net_amount, status, created_by, updated_by
) VALUES (
    #{settlementId}, #{sellerId}, #{periodStart}, #{periodEnd},
    #{grossAmount}, #{commissionAmount}, #{netAmount}, 'PENDING', #{createdBy}, #{updatedBy}
)
ON DUPLICATE KEY UPDATE settlement_id = settlement_id

mapper.update:
UPDATE settlement
SET status = 'PAID', updated_at = NOW(), updated_by = #{operatorId}
WHERE settlement_id = #{settlementId} AND status IN ('PENDING', 'CONFIRMED')

