SELECT 
FROM settlement
WHERE is_deleted = 0

    AND seller_id = #{sellerId}


    AND period_start = #{periodStart}

ORDER BY period_start DESC, seller_id ASC
LIMIT #{offset}, #{size}

SELECT COUNT(*)
FROM settlement
